CREATE TABLE IF NOT EXISTS settings(key text PRIMARY KEY,value jsonb NOT NULL);
CREATE TABLE packages(id serial PRIMARY KEY,name text UNIQUE NOT NULL,targets jsonb NOT NULL);
CREATE TABLE organisations(id serial PRIMARY KEY,name text NOT NULL,package_id integer NOT NULL REFERENCES packages(id));
CREATE TABLE users(id serial PRIMARY KEY,name text NOT NULL,email text UNIQUE NOT NULL,password text NOT NULL,role text NOT NULL CHECK(role IN ('client','agent','lead','manager','admin','owner')),organisation_id integer REFERENCES organisations(id),active boolean NOT NULL DEFAULT true,CHECK(role <> 'client' OR organisation_id IS NOT NULL));
CREATE TABLE tickets(id serial PRIMARY KEY,number text UNIQUE,title text NOT NULL,description text NOT NULL,organisation_id integer NOT NULL REFERENCES organisations(id),creator_id integer NOT NULL REFERENCES users(id),assignee_id integer REFERENCES users(id),category text NOT NULL,priority text NOT NULL,status text NOT NULL DEFAULT 'New',source text NOT NULL DEFAULT 'portal',created_at timestamptz NOT NULL DEFAULT now(),updated_at timestamptz NOT NULL DEFAULT now(),responded_at timestamptz,resolved_at timestamptz,closed_at timestamptz,response_minutes integer NOT NULL,resolution_minutes integer NOT NULL,calendar jsonb NOT NULL,elapsed_minutes numeric NOT NULL DEFAULT 0,last_tick timestamptz NOT NULL DEFAULT now(),warning_sent boolean NOT NULL DEFAULT false,breach_sent boolean NOT NULL DEFAULT false,rating integer CHECK(rating BETWEEN 1 AND 5),custom_fields jsonb NOT NULL DEFAULT '{}');
CREATE TABLE comments(id serial PRIMARY KEY,ticket_id integer REFERENCES tickets(id),user_id integer REFERENCES users(id),body text NOT NULL,internal boolean NOT NULL DEFAULT false,created_at timestamptz DEFAULT now());
CREATE TABLE audit(id bigserial PRIMARY KEY,ticket_id integer REFERENCES tickets(id),user_id integer REFERENCES users(id),action text NOT NULL,details jsonb DEFAULT '{}',created_at timestamptz DEFAULT now());
CREATE FUNCTION prevent_audit_mutation() RETURNS trigger LANGUAGE plpgsql AS $$ BEGIN RAISE EXCEPTION 'Audit records are immutable'; END $$;
CREATE TRIGGER immutable_audit BEFORE UPDATE OR DELETE ON audit FOR EACH ROW EXECUTE FUNCTION prevent_audit_mutation();
CREATE TABLE notifications(id bigserial PRIMARY KEY,user_id integer REFERENCES users(id),ticket_id integer REFERENCES tickets(id),message text NOT NULL,read_at timestamptz,created_at timestamptz DEFAULT now());
CREATE TABLE outbox(id bigserial PRIMARY KEY,email text NOT NULL,subject text NOT NULL,body text NOT NULL,attempts integer DEFAULT 0,sent_at timestamptz,next_attempt timestamptz DEFAULT now());
CREATE TABLE attachments(id serial PRIMARY KEY,ticket_id integer REFERENCES tickets(id),name text NOT NULL,path text NOT NULL,mime text NOT NULL,size integer NOT NULL,created_at timestamptz DEFAULT now());
CREATE TABLE email_receipts(message_id text PRIMARY KEY,ticket_id integer REFERENCES tickets(id));
CREATE TABLE ticket_links(ticket_id integer REFERENCES tickets(id),related_id integer REFERENCES tickets(id),PRIMARY KEY(ticket_id,related_id),CHECK(ticket_id<>related_id));
CREATE INDEX tickets_org ON tickets(organisation_id);CREATE INDEX tickets_status ON tickets(status);CREATE INDEX outbox_pending ON outbox(next_attempt) WHERE sent_at IS NULL;
